PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "first_contact" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "company" varchar(100) NOT NULL, "inquiry_type" varchar(20) NOT NULL, "subject" varchar(200) NOT NULL, "message" text NOT NULL, "created_at" datetime NOT NULL, "is_read" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "first_jobposting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "department" varchar(20) NOT NULL, "job_type" varchar(20) NOT NULL, "experience_level" varchar(20) NOT NULL, "location" varchar(100) NOT NULL, "remote_allowed" bool NOT NULL, "description" text NOT NULL, "responsibilities" text NOT NULL, "requirements" text NOT NULL, "nice_to_have" text NOT NULL, "benefits" text NOT NULL, "salary_min" integer NULL, "salary_max" integer NULL, "equity_offered" bool NOT NULL, "is_active" bool NOT NULL, "applications_count" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "deadline" date NULL, "company_logo" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "first_jobapplication" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "first_name" varchar(50) NOT NULL, "last_name" varchar(50) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "current_location" varchar(100) NOT NULL, "willing_to_relocate" bool NOT NULL, "current_company" varchar(100) NOT NULL, "current_role" varchar(100) NOT NULL, "years_experience" varchar(20) NOT NULL, "resume" varchar(100) NOT NULL, "cover_letter" text NOT NULL, "portfolio_url" varchar(200) NOT NULL, "expected_salary" integer NULL, "earliest_start_date" date NOT NULL, "visa_sponsorship_required" bool NOT NULL, "reference1_name" varchar(100) NOT NULL, "reference1_email" varchar(254) NOT NULL, "reference1_phone" varchar(20) NOT NULL, "reference1_relation" varchar(100) NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "applied_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "job_posting_id" bigint NOT NULL REFERENCES "first_jobposting" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "first_productcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "category_type" varchar(20) NOT NULL UNIQUE, "description" text NOT NULL, "short_description" varchar(200) NOT NULL, "image" varchar(100) NOT NULL, "icon" varchar(50) NOT NULL, "is_active" bool NOT NULL, "display_order" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "first_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "short_description" varchar(300) NOT NULL, "detailed_description" text NOT NULL, "specifications" text NOT NULL, "dimensions" varchar(100) NOT NULL, "weight" varchar(50) NOT NULL, "power_requirements" varchar(100) NOT NULL, "capacity" varchar(100) NOT NULL, "main_image" varchar(100) NOT NULL, "gallery_images" text NOT NULL, "video_url" varchar(200) NOT NULL, "brochure" varchar(100) NOT NULL, "price_range" varchar(100) NOT NULL, "is_available" bool NOT NULL, "lead_time" varchar(50) NOT NULL, "key_features" text NOT NULL, "applications" text NOT NULL, "benefits" text NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" varchar(300) NOT NULL, "is_featured" bool NOT NULL, "is_active" bool NOT NULL, "display_order" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "first_productcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "first_productinquiry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "company" varchar(100) NOT NULL, "inquiry_type" varchar(20) NOT NULL, "message" text NOT NULL, "created_at" datetime NOT NULL, "is_responded" bool NOT NULL, "product_id" bigint NOT NULL REFERENCES "first_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "first_testimonial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "role" varchar(50) NOT NULL, "company_or_location" varchar(150) NOT NULL, "country" varchar(50) NOT NULL, "quote" text NOT NULL, "impact_metric" varchar(100) NOT NULL, "impact_icon" varchar(50) NOT NULL, "photo" varchar(100) NOT NULL, "video_url" varchar(200) NOT NULL, "is_active" bool NOT NULL, "is_featured" bool NOT NULL, "display_order" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "first_mediacoveragearticle" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "publication" varchar(100) NOT NULL, "category" varchar(20) NOT NULL, "icon" varchar(20) NOT NULL, "description" text NOT NULL, "article_url" varchar(200) NOT NULL, "featured_image" varchar(100) NOT NULL, "publication_date" date NOT NULL, "is_featured" bool NOT NULL, "external_publication" bool NOT NULL, "is_active" bool NOT NULL, "display_order" integer NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" varchar(300) NOT NULL, "clicks_count" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "first_newslettersubscriber" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL UNIQUE, "subscribed_at" datetime NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "first_blogpost" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "category" varchar(20) NOT NULL, "author_name" varchar(100) NOT NULL, "author_title" varchar(100) NOT NULL, "author_image" varchar(100) NOT NULL, "excerpt" varchar(300) NOT NULL, "content" text NOT NULL, "featured_image" varchar(100) NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" varchar(300) NOT NULL, "tags" varchar(200) NOT NULL, "is_published" bool NOT NULL, "is_featured" bool NOT NULL, "views_count" integer NOT NULL, "comments_count" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "published_at" datetime NULL, "external_url" varchar(200) NOT NULL, "content_sections" text NOT NULL, "custom_css" text NOT NULL, "custom_js" text NOT NULL, "estimated_read_time" integer NOT NULL, "gallery_images" text NOT NULL, "video_url" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "first_faq" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question" varchar(255) NOT NULL, "answer" text NOT NULL, "is_featured" bool NOT NULL, "order" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_user_groups_user_id_group_id_94350c0c_uniq" ON "auth_user_groups" ("user_id", "group_id");
CREATE INDEX "auth_user_groups_user_id_6a12ed8b" ON "auth_user_groups" ("user_id");
CREATE INDEX "auth_user_groups_group_id_97559544" ON "auth_user_groups" ("group_id");
CREATE UNIQUE INDEX "auth_user_user_permissions_user_id_permission_id_14a6b632_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "auth_user_user_permissions_user_id_a95ead1b" ON "auth_user_user_permissions" ("user_id");
CREATE INDEX "auth_user_user_permissions_permission_id_1fbb5f2c" ON "auth_user_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE UNIQUE INDEX "first_jobapplication_job_posting_id_email_34931725_uniq" ON "first_jobapplication" ("job_posting_id", "email");
CREATE INDEX "first_jobapplication_job_posting_id_232b80a4" ON "first_jobapplication" ("job_posting_id");
CREATE INDEX "first_product_category_id_b15feafa" ON "first_product" ("category_id");
CREATE INDEX "first_productinquiry_product_id_f5a2a1ee" ON "first_productinquiry" ("product_id");
COMMIT;
