INSERT INTO first_jobposting VALUES(1,'Mechanical Engineer','engineering','full_time','mid','Bangalore, India',0,'We are looking for a skilled Mechanical Engineer to join our R&D team...',unistr('\u000a- Design and develop mechanical components for agricultural machinery\u000a- Create detailed 3D models and technical drawings using CAD software\u000a- Collaborate with cross-functional teams to optimize product designs\u000a- Conduct structural and thermal analyses\u000a- Oversee prototyping and testing of new designs\u000a                '),unistr('\u000a- B.Tech/M.Tech in Mechanical Engineering\u000a- 3-5 years experience in product development\u000a- Proficiency in SolidWorks or similar CAD software\u000a- Strong understanding of GD&T and manufacturing processes\u000a- Experience with agricultural machinery is a plus\u000a                '),unistr('\u000a- Experience with automation systems\u000a- Knowledge of IoT and sensor integration\u000a- Familiarity with rapid prototyping technologies\u000a                '),unistr('\u000a- Competitive salary package\u000a- Health insurance for self and family\u000a- Professional development opportunities\u000a- Flexible work hours\u000a- Stock options\u000a                '),1000000,1800000,1,1,0,'2025-07-12 10:27:53.199327','2025-07-12 10:27:53.199340','2025-08-11','');
INSERT INTO first_jobposting VALUES(2,'Mechatronics Internship','engineering','internship','entry','Bangalore, India',0,'Join our innovative team as a Mechatronics Intern...',unistr('\u000a- Assist in the development of automated systems\u000a- Work on integration of sensors and actuators\u000a- Help with testing and validation of prototypes\u000a- Document technical processes and results\u000a                '),unistr('\u000a- Currently pursuing B.Tech/M.Tech in Mechatronics/Mechanical/Electronics\u000a- Strong foundation in mechanical and electronic systems\u000a- Basic programming skills (Python/Arduino)\u000a- Eager to learn and contribute to real projects\u000a                '),unistr('\u000a- Previous internship experience\u000a- Knowledge of ROS\u000a- Experience with microcontrollers\u000a                '),unistr('\u000a- Stipend based on capabilities\u000a- Certificate upon completion\u000a- Potential for pre-placement offer\u000a- Hands-on experience with cutting-edge technology\u000a                '),25000,40000,0,1,0,'2025-07-12 10:27:53.203243','2025-07-12 10:27:53.203259','2025-07-27','');
INSERT INTO first_productcategory VALUES(1,'Size Graders','size-graders','size_graders','Our size graders use advanced optical and mechanical sorting technology to classify crops based on their physical dimensions. Perfect for ensuring uniform quality and meeting specific market requirements.','Precision size-based sorting machines for uniform crop grading','','fas fa-ruler-horizontal',1,1,'2025-07-11 10:22:06.020363','2025-07-13 07:25:36.072253');
INSERT INTO first_productcategory VALUES(2,'Quality Graders','quality-graders','quality_graders','Intelligent quality grading systems that use computer vision and AI to assess crop quality, color, defects, and overall grade. Ensures consistent quality standards across your entire harvest.','AI-powered quality assessment and classification systems','','fas fa-star',1,2,'2025-07-11 10:22:06.025511','2025-07-13 07:25:36.085228');
INSERT INTO first_productcategory VALUES(3,'Weight Graders','weight-graders','weight_graders','Accurate weight-based grading systems that sort crops into precise weight categories. Essential for premium packaging and meeting specific weight requirements for different market segments.','High-precision weight-based sorting and classification','','fas fa-weight',1,3,'2025-07-11 10:22:06.029983','2025-07-13 07:25:36.089530');
INSERT INTO first_productcategory VALUES(4,'Cleaning Machines','cleaning-machines','cleaning_machines','Comprehensive cleaning solutions that remove impurities, foreign materials, and damaged crops. Multi-stage cleaning process ensures your crops meet the highest hygiene and quality standards.','Advanced cleaning and debris removal systems','','fas fa-apple-alt',1,4,'2025-07-11 10:22:06.034839','2025-07-13 07:25:36.094149');
INSERT INTO first_productcategory VALUES(5,'Packing Robots','packing-robots','packing_robots','State-of-the-art robotic systems for automated packaging, handling, and palletizing. Increase efficiency while reducing labor costs and ensuring consistent packaging quality.','Automated robotic packaging and handling solutions','','fas fa-robot',1,5,'2025-07-11 10:22:06.039702','2025-07-13 07:25:36.098282');
INSERT INTO first_product VALUES(37,'Segritech Apple Size Grading Machine','segritech-apple-size-grading-machine','Compact apple grading machine with roller-based sorting system. Perfect for farms and mandis with 200-250 box/day capacity.',unistr('The Segritech Apple Size Grading Machine is a compact and efficient agricultural machine designed for small to medium-scale apple producers. With a robust roller-based grading mechanism, this model provides high accuracy in size grading, ensuring better pricing and packaging for apple growers and aggregators.\u000a\u000aFeatures a durable construction with food-grade materials and integrated cleaning system, making it perfect for farm and mandi operations with 200-250 box/day capacity.'),'{"Capacity": "200-250 box per day", "Grading Output": "6 Grades", "Dimensions": "10 ft (L) x 4 ft (W) x 4 ft (H)", "Power": "1.5 kW, Single/3 Phase", "Material": "Stainless Steel, Food-grade Nylon", "Features": "Cleaning & Grading, Portable Design"}','','','','','','','','','Contact for Pricing',1,'','["Roller-based size grading system", "Integrated cleaning & drying section", "Food-grade materials (FDA-compliant)", "6-grade output capacity", "Portable design with wheels", "Built for Indian conditions"]','["Small to medium farms", "Fruit packhouses", "Agricultural cooperatives"]','["Better market pricing", "Reduced labor costs", "Consistent grading quality", "Portable and easy to use"]','','',1,1,0,'2025-07-13 07:25:36.328342','2025-07-13 07:25:36.328359',1);
INSERT INTO first_product VALUES(38,'Segritech Orange Grading Machine','segritech-orange-grading-machine','Compact size grading machine designed specifically for oranges with reliable performance and space efficiency',unistr('Segritech Orange Grading Machine - Specialized Citrus Sorting System\u000a\u000aThe Segritech Orange Grading Machine is specifically designed for orange grading operations, offering precision sizing in a space-efficient design. Built for Indian agricultural operations, this compact machine delivers reliable performance for cooperative societies, small processing units, and citrus specialty graders.\u000a\u000aFeatures advanced mechanical sorting technology optimized for orange characteristics, ensuring consistent size classification while maintaining fruit quality. The system provides cost-effective sorting solutions with durable construction designed for continuous operation in agricultural environments.\u000a\u000aPerfect for operations requiring dedicated orange processing with space constraints and budget considerations.'),'{"Model": "Segritech OGM-250", "Processing Capacity": "250 kg/hour", "Accuracy": "98.5%", "Power Consumption": "3.0 kW", "Dimensions": "1.8m x 1.2m x 1.5m", "Weight": "450 kg", "Material": "Mild Steel with food-grade coating", "Output Grades": "3-5 size categories", "Voltage": "220V/440V, 50 Hz"}','','','','','','','','','₹25,000 - ₹32,000',1,'','["Compact design for space efficiency", "Processing capacity: 250kg/hour", "Easy maintenance and operation", "Cost-effective solution", "Durable construction", "Low power consumption", "Optimized for orange characteristics", "Consistent size classification", "Simple controls and operation", "Portable design"]','["Small processing units", "Cooperative societies", "Specialty crop grading", "Regional distribution centers", "Citrus packaging facilities", "Local market preparation", "Export pre-processing", "Farm-level grading"]','["Lower initial investment", "Space-efficient design", "Reliable performance", "Easy to operate", "Reduced labor costs", "Consistent grading quality", "Improved market pricing", "Quick return on investment"]','Segritech Orange Grading Machine | Compact Citrus Sorting','Segritech Orange Grading Machine - Compact, cost-effective orange sorting solution. 250kg/hour capacity with 98.5% accuracy for small processing units.',0,1,0,'2025-07-13 07:25:36.333002','2025-07-13 07:25:36.407622',1);
INSERT INTO first_product VALUES(39,'Segritech Minisort','segritech-minisort','The Segritech Minisort is a high-capacity, AI-based sorting machine that processes up to 2 tons per hour. It uses advanced camera vision and smart algorithms to detect size, shape, color, and defects across multiple fruit varieties, ensuring export-grade consistency. Built for Indian farms and packhouses with rugged construction and rapid support.',unistr('The Segritech Minisort is an advanced AI-powered grading machine designed for high-volume fruit sorting across multiple varieties including pomegranates, apples, oranges, and other round fruits. With the capacity to process up to 2 tons per hour, it grades fruits based on size, shape, color, and skin defects using camera vision and AI synchronization.\u000a\u000aIdeal for packhouses, mandis, exporters, and farmer cooperatives, the machine ensures export-grade sorting quality with real-time reporting.'),'{"Capacity": "2 tons per hour (2000 kg/hour)", "Fruit Types": "Pomegranates, apples, oranges, citrus fruits, and other round fruits", "Grading Parameters": "Size, shape, color, and external defects", "Technology": "AI, camera vision, roller assist, and conveyor sync", "Output Grades": "5 to 6 grades (customizable)", "Construction Material": "Stainless steel, mild steel, aluminum, and food-grade plastic", "Machine Dimensions": "10 feet length, 5 feet width, 5 feet height", "Power Requirement": "3.5 kW or 5 HP", "Voltage": "440V (3-phase) or 220V (single phase), 50 Hz", "Drive Mechanism": "Motor and conveyor belt synced with AI", "Feeding Mechanism": "Vibratory or conveyor-fed", "Mobility": "Industrial-grade caster wheels"}','','','','','','','','','Contact for Pricing',1,'','["AI-powered defect detection", "Camera vision technology", "Real-time quality analysis", "Export-grade sorting", "High capacity processing", "Robust construction"]','["Packhouses", "Mandis", "Exporters", "Farmer cooperatives", "Large-scale processors"]','["Export-grade sorting quality", "High processing capacity", "Real-time quality reporting", "Robust construction", "Customizable grading", "Easy maintenance"]','','',1,1,0,'2025-07-13 07:25:36.338205','2025-07-13 07:25:36.390288',2);
INSERT INTO first_product VALUES(40,'Segritech : Weight Grader for Fruits','segritech-weight-grader-for-fruits','Ultra-precise weight-based grading system for density sorting and export preparation.',unistr('The Segritech Weight Grader for Fruits delivers exceptional accuracy in weight-based grading, essential for export markets requiring strict weight specifications. Features advanced load cells and vibration dampening for consistent results.\u000a\u000aOur weight grader ensures precise sorting based on weight, making it ideal for export quality standards. The machine''s advanced technology and robust construction guarantee reliable performance.'),'{"Processing Capacity": "300 kg/hour", "Weighing Accuracy": "\u00b10.1g", "Weight Range": "0.1g - 50g per grain", "Power Consumption": "4.5 kW", "Dimensions": "2.2m x 1.6m x 1.8m", "Weight": "720 kg"}','','','','','','','','','₹45,000 - ₹60,000',1,'','["Precision weighing \u00b10.1g accuracy", "Density-based separation", "Export quality standards compliance", "Multiple weight categories", "Vibration dampening system", "Digital weight display"]','["Export preparation facilities", "Premium seed processing", "Quality certification labs", "High-value crop sorting"]','["Access to premium export markets", "Consistent weight specifications", "Higher selling prices", "Quality certification compliance"]','','',1,1,0,'2025-07-13 07:25:36.343126','2025-07-13 07:25:36.398167',3);
INSERT INTO first_product VALUES(43,'SegriPack by Segritech','segripack-by-segritech','Smart Robotic Packing System for Graded Fresh Produce',unistr('SegriPack by Segritech - Smart Robotic Packing System for Graded Fresh Produce\u000a\u000aSegriPack is Segritech''s flagship automated packaging solution designed specifically for graded fresh produce. This intelligent robotic system combines precision handling with smart weighing technology to deliver consistent, retail-ready packaging for fruits and vegetables.\u000a\u000aBuilt for Indian agricultural operations, SegriPack offers the perfect balance of automation, reliability, and cost-effectiveness. Whether you''re packaging pomegranates, apples, citrus fruits, or other fresh produce, SegriPack ensures professional presentation while reducing labor dependency.\u000a\u000aKEY FEATURES:\u000a• Smart robotic arms with gentle produce handling\u000a• Integrated precision weighing system\u000a• Multi-format packaging capability (bags, trays, boxes)\u000a• Vision-guided quality control\u000a• Real-time production monitoring\u000a• Food-grade construction materials\u000a• Easy operation with minimal training\u000a\u000aBENEFITS:\u000a• Consistent packaging quality and presentation\u000a• Reduced labor costs and dependency\u000a• Increased packaging speed and throughput\u000a• Minimized product damage during handling\u000a• Enhanced food safety and hygiene standards\u000a• Improved operational efficiency'),'{"Model": "SegriPack SP-2000", "Packaging Speed": "150-200 packages/hour", "Weight Range": "0.5kg - 25kg", "Weight Accuracy": "\u00b12g", "Package Formats": "Bags, trays, boxes, nets", "Produce Types": "Fruits, vegetables, graded produce", "Power Consumption": "8 kW", "Dimensions": "3.5m x 2.5m x 2.2m", "Construction": "Food-grade stainless steel", "Control System": "PLC with touchscreen interface"}','','','','','','','','','Contact for Pricing',1,'','["Smart robotic arm automation", "Precision weighing and portioning", "Multi-format packaging capability", "Vision-guided quality control", "Gentle produce handling technology", "Food-grade construction materials", "Real-time production monitoring", "Easy operation interface", "Minimal training requirement", "Consistent packaging quality"]','["Fresh produce packaging facilities", "Export packaging centers", "Agricultural cooperatives", "Commercial fruit processing", "Vegetable packing houses", "Retail packaging operations", "Graded produce packaging", "Quality-controlled packaging lines"]','["Consistent retail-ready packaging", "Reduced labor dependency", "Enhanced food safety compliance", "Increased packaging throughput", "Minimized product damage", "Improved operational efficiency", "Professional package presentation", "Cost-effective automation solution"]','SegriPack by Segritech | Smart Robotic Packing System for Fresh Produce','SegriPack - Smart robotic packing system for graded fresh produce. Automated packaging with precision weighing, gentle handling, and consistent quality presentation.',1,1,0,'2025-07-13 07:25:36.358517','2025-07-13 07:25:36.423082',5);
INSERT INTO first_product VALUES(45,'Segriwax - Waxing & Cleaning Machine','segriwax-waxing-cleaning-machine','Compact, Portable, High-Speed Cleaning & Waxing System for Fresh Produce',unistr('Segriwax™ - Next-Generation Fruit Cleaning and Waxing Machine by Segritech\u000a\u000aSegriwax™ is a next-generation fruit cleaning and waxing machine tailored for India''s decentralized post-harvest ecosystem. Designed for efficiency, affordability, and mobility, Segriwax brings industrial grade performance into a compact, field-deployable solution.\u000a\u000aWhether you''re a farmer looking to enhance shelf life, or an exporter aiming for retail-grade presentation — Segriwax delivers the finish your produce deserves.\u000a\u000aPRODUCT INTRODUCTION:\u000aSegriwax™ is specifically designed for India''s diverse agricultural landscape, offering professional-grade cleaning and waxing capabilities in a portable, cost-effective package. This machine combines advanced cleaning technology with precision waxing application to ensure your fresh produce meets international quality standards.\u000a\u000aKEY BENEFITS:\u000a• Enhanced shelf life of fresh produce\u000a• Retail-grade presentation for premium markets\u000a• Compact and portable design for field deployment\u000a• Industrial-grade performance in affordable package\u000a• Suitable for farmers, cooperatives, and exporters\u000a• Easy operation with minimal training required'),'{"Type": "Cleaning & Waxing Machine", "Model": "Segriwax\u2122", "Design": "Compact & Portable", "Performance": "Industrial Grade", "Application": "Fresh Produce Processing", "Deployment": "Field Ready", "Operation": "High-Speed Processing", "Target Market": "Farmers, Cooperatives, Exporters", "Finish Quality": "Retail Grade", "Maintenance": "Easy & Minimal"}','','','','','','','','','Contact for Pricing',1,'','["Next-generation cleaning and waxing technology", "Compact and portable design", "High-speed processing capability", "Industrial-grade performance", "Field-deployable solution", "Cost-effective operation", "Enhanced shelf life for produce", "Retail-grade finish quality", "Easy maintenance and operation", "Suitable for various fruit types"]','["Small to medium farm operations", "Agricultural cooperatives", "Export packaging centers", "Fresh produce processing units", "Fruit packhouses", "Post-harvest processing facilities", "Regional collection centers", "Farmer producer organizations"]','["Enhanced shelf life of fresh produce", "Premium market presentation", "Reduced post-harvest losses", "Improved market pricing", "Professional finish quality", "Portable field deployment", "Cost-effective processing", "Easy operation and maintenance", "Suitable for decentralized operations", "Meets international quality standards"]','Segriwax Waxing & Cleaning Machine | Segritech Fresh Produce Processing','Segriwax™ by Segritech - Compact, portable, high-speed cleaning & waxing system for fresh produce. Industrial-grade performance for enhanced shelf life and retail presentation.',1,1,0,'2025-07-13 07:25:36.370277','2025-07-13 07:25:36.370293',4);
